/*
 * A179826  Primes that can be obtained from composite numbers by
 *          interchanging the first and last digits.
 * https://oeis.org/A179826
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  base, nonn
 * Formula:   not stated
 * Range:     u8 n <= 16, u16 n <= 60, u32 n <= 60, u64 n <= 60, u128 n <= 60,
 *            big any n
 * Helpers:   is_prime_big
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Sequence A179826 (primes obtainable by reversing composite numbers). */
/* The sequence is generated by checking each integer m ≥ 10 in turn.
   If m is composite, its decimal digits are reversed (leading zeros are
   dropped).  If the reversed number is prime, it is appended to the
   output list.  a(1) = 41, a(2) = 61, a(3) = 2, … */

#include <stdbool.h>
#include <stdint.h>
#include <stdlib.h>
#include "../utils/is_prime_big.h"

/* Ensure the cache can hold 'need' elements. */
static void grow_seq_cache(seq_t **arr, size_t *cap, size_t need)
{
    if (*cap < need) {
        size_t new_cap = (*cap) ? (*cap << 1) : 16;
        while (new_cap < need) new_cap <<= 1;
        seq_t *tmp = (seq_t *)malloc(new_cap * sizeof(seq_t));
        if (*arr) {
            for (size_t i = 0; i < *cap; ++i) tmp[i] = (*arr)[i];
            free(*arr);
        }
        *arr   = tmp;
        *cap   = new_cap;
    }
}

seq_t a(idx_t n)
{
    static seq_t *cache      = NULL;
    static size_t cache_cap  = 0;
    static size_t cache_len  = 0;
    static idx_t  next       = 4;          /* start from the smallest composite */

    while (cache_len < n) {
        if (next >= 10) {                  /* at least two digits */
            if (!is_prime_big((seq_t)next)) {
                /* reverse decimal digits, dropping leading zeros */
                idx_t m = next;
                seq_t rev = 0;
                while (m > 0) {
                    rev = rev * 10 + (seq_t)(m % 10);
                    m /= 10;
                }
                if (is_prime_big(rev)) {
                    grow_seq_cache(&cache, &cache_cap, cache_len + 1);
                    cache[cache_len++] = rev;
                }
            }
        }
        ++next;
    }
    return cache[n - 1];
}
